import java.io.IOException;
import java.net.InetAddress;
import java.net.ServerSocket;
import java.util.List;

public class PortScannerLocalTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static String scan(int[] ports, int timeoutMs) {
        try {
            List<Integer> result = PortScannerLocal.openPorts(ports, timeoutMs);
            return result == null ? "openPorts returned null" : result.toString();
        } catch (Throwable t) {
            return "openPorts threw " + t.getClass().getSimpleName();
        }
    }

    static int size(int[] ports, int timeoutMs) {
        try {
            List<Integer> result = PortScannerLocal.openPorts(ports, timeoutMs);
            return result == null ? -1 : result.size();
        } catch (Throwable t) {
            return -2;
        }
    }

    static void closeQuietly(ServerSocket socket) {
        if (socket != null) {
            try {
                socket.close();
            } catch (IOException ignored) {
                // nothing useful to do
            }
        }
    }

    public static void main(String[] args) throws Exception {
        ServerSocket alpha = null;
        ServerSocket beta = null;
        ServerSocket doomed = null;
        try {
            InetAddress loopback = InetAddress.getByName("127.0.0.1");
            alpha = new ServerSocket(0, 8, loopback);
            beta = new ServerSocket(0, 8, loopback);
            doomed = new ServerSocket(0, 8, loopback);

            int portA = alpha.getLocalPort();
            int portB = beta.getLocalPort();
            int closedPort = doomed.getLocalPort();
            doomed.close();
            doomed = null;

            check("a listening port is reported open", "[" + portA + "]",
                    scan(new int[] { portA }, 300));
            check("a closed port is left out", "[]",
                    scan(new int[] { closedPort }, 300));
            check("mixed scan keeps only the open ports", "[" + portA + ", " + portB + "]",
                    scan(new int[] { portA, closedPort, portB }, 300));
            check("results follow the order of the input array", "[" + portB + ", " + portA + "]",
                    scan(new int[] { portB, portA }, 300));
            check("an empty array scans to an empty list", "[]", scan(new int[] {}, 300));
            check("two open ports give a list of size 2", 2, size(new int[] { portA, portB }, 300));

            closeQuietly(alpha);
            alpha = null;
            check("a port stops being open once its server closes", "[" + portB + "]",
                    scan(new int[] { portA, portB }, 300));
        } finally {
            closeQuietly(alpha);
            closeQuietly(beta);
            closeQuietly(doomed);
        }

        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

