import java.io.IOException;
import java.net.InetSocketAddress;
import java.net.Socket;
import java.util.ArrayList;
import java.util.List;

public class PortScannerLocal {

    public static List<Integer> openPorts(int[] ports, int timeoutMs) {
        List<Integer> open = new ArrayList<>();
        for (int port : ports) {
            Socket socket = new Socket();
            try {
                socket.connect(new InetSocketAddress("127.0.0.1", port), timeoutMs);
                open.add(port);
            } catch (IOException refused) {
                // Nothing is listening there -- leave it out of the list.
            } finally {
                try {
                    socket.close();
                } catch (IOException ignored) {
                    // nothing useful to do
                }
            }
        }
        return open;
    }
}
